{"version":3,"file":"page-CATfWk-0.js","sources":["../../../pages/incidents/page.js"],"sourcesContent":["import {html, css} from 'lit';
import {customElement} from 'lit/decorators.js';
import {AIUXElement} from '@servicenow/aiux/aiux-components-core';
import {i18n} from '@servicenow/aiux/aiux-services';
import '@servicenow/aiux/aiux-components-list';
import {ListDataManager} from '@servicenow/aiux/aiux-components-list';

@customElement('x-snc-hauri-demo-3-incidents-page')
export default class IncidentsPage extends AIUXElement {
  static styles = css`
    :host {
      display: contents;
    }
  `;

  static async loader(ctx) {
    const data = await ListDataManager.fetch({
      table: 'incident',
      query: ctx.query?.sysparm_query || 'active=true',
      view: ''
    }).catch(() => null);

    return {data};
  }

  render() {
    const {data} = this.loaderData || {};

    return html`
      <div class="mx-auto flex max-w-7xl flex-col gap-6 p-4 lg:p-8">
        <div class="flex flex-col gap-2">
          <div class="aiux-badge aiux-badge-primary aiux-badge-outline">
            ${i18n.getMessage('Example page')}
          </div>
          <h2 class="text-3xl font-bold tracking-tight">
            ${i18n.getMessage('Incidents')}
          </h2>
          <p class="max-w-3xl">
            ${i18n.getMessage(
              'This page uses aiux-list-connected and ListDataManager to render a ServiceNow incident list.'
            )}
          </p>
        </div>
        <section class="aiux-card border border-base-300 bg-base-100 shadow-sm">
          <div class="aiux-card-body p-6">
            <aiux-list-connected
              table="incident"
              query="active=true"
              .data=${data}
              .pageSize=${10}
              .listOptions=${{
                heading: i18n.getMessage('Active incidents'),
                selectionEnabled: false,
                selectAllEnabled: false,
                showRefreshButton: true,
                showZingSearch: true,
                showConditionBuilderButton: true,
                showEditColumnsButton: true,
                showCopyURLButton: false,
                showCount: true,
                showReadableFixedQuery: true
              }}
            ></aiux-list-connected>
          </div>
        </section>
      </div>
    `;
  }
}
"],"names":["styles","data","ctx","ListDataManager","fetch","query","view","sysparm_query","catch","render","loaderData","selectionEnabled","selectAllEnabled","showRefreshButton","showZingSearch","showConditionBuilderButton","showEditColumnsButton","showCopyURLButton","showCount","showReadableFixedQuery"],"mappings":";;6QASSA,MAAAA;;;;IAOL,aAAMC,OAAOC,CAAMC,CAAAA,CAMXF,MAAAA,CAAIA,KALH,MAAAE,EAAAC,KAAA,CAAA,CACPC,MAAOH,WACPI,MAAMJ,EAAAG,KAAA,EAAAE,eAAA,cACLC,KAAM,KAETA,KAAO,CAAA,IAAA,KACT,CAEAC,SACE,CAEA,GAAA,OAAY,CAAA,CAAA,IAAA,CAAAC,UAAA,EAAA,CAAA;;;;;;;;;;;;;;;;;;oBAqBQ,EAAAT,EAAE;6BACC;8BAEXU,QAAAA,EAAAA,UAAkB,CAAA,oBAClBC,iBAAkB,CAAA,EAClBC,iBAAAA,CAAAA,EACAC,kBAAgB,CAAA,EAChBC,eAAAA,CAAAA,EACAC,2BAAuB,CAAA,EACvBC,sBAAmB,CAAA,EACnBC,kBAAW,CAAA,EACXC,UAAAA,CAAAA,EACAA,uBAAA,CAAA;;;;;IAMd,CAAA,AACF"}
